-- Прилагательные (часть 1/8)
INSERT OR IGNORE INTO UltraWords (value, typeId, partOfSpeechId, isDeclinable, link, DateTimeSaving, Popularity, IsModern, Comment)
SELECT
    value,
    7 AS typeId,
    2 AS partOfSpeechId,
    1 AS isDeclinable,
    'https://codenlp.ru/slovar/spisok-prilagatelnyih-russkogo-yazyika.html' AS link,
    datetime('now', 'localtime') AS DateTimeSaving,
    popularity,
    isModern,
    Comment
FROM (
    SELECT 'Абхазский' AS value, 1 as popularity, 1 as isModern, NULL as Comment UNION ALL
    SELECT 'Авангардный' AS value, 1 as popularity, 1 as isModern, NULL as Comment UNION ALL
