SELECT
    value,
    7 AS typeId,
    2 AS partOfSpeechId,
    1 AS isDeclinable,
    'https://codenlp.ru/slovar/spisok-prilagatelnyih-russkogo-yazyika.html' AS link,
    datetime('now', 'localtime') AS DateTimeSaving,
    popularity,
    isModern,
    Comment
