SELECT
    value,
    7 AS typeId,
    2 AS partOfSpeechId,
    1 AS isDeclinable,
    'https://codenlp.ru/slovar/spisok-prilagatelnyih-russkogo-yazyika.html' AS link,
    datetime('now', 'localtime') AS DateTimeSaving,
    popularity,
    isModern,
    Comment
FROM (
    SELECT 'Николаевский' AS value, 1 as popularity, 1 as isModern, NULL as Comment UNION ALL
    SELECT 'Николо' AS value, 1 as popularity, 1 as isModern, NULL as Comment UNION ALL
    SELECT 'Никотиновый' AS value, 1 as popularity, 1 as isModern, NULL as Comment UNION ALL
